/* Rounded: the default look with pill-like corners. Colors come from the user's palette.
   Every corner follows the radius tokens; the active tab keeps its own radius. */

/* --- rounded set --- */
/* One rule for every control: anything one line tall is a pill, like the message composer.
   Panels, cards and text areas follow the larger radius tokens. Rail thumbnails and menu
   buttons are circles, like the persona avatar and the send buttons. */
[data-skin-part="button"]:not([data-skin-variant="link"]),
[data-skin-part="input"]:not(:has(textarea)),
[data-skin-part="tabs"],
[data-skin-part="tab"],
[data-skin-part="chip"],
[data-skin-part="switch"],
[data-skin-part="checkbox"] { border-radius: 9999px !important; }
[data-skin-part="rail-icon"],
[data-skin-part="rail-icon"] :is(img, div, span),
[data-skin-part="sidebar-rail"] :is(button, img) { border-radius: 9999px !important; }
